.lst-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.lst-root,.lst-root *,.lst-root *::before,.lst-root *::after{box-sizing:border-box}
.lst-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.lst-root img{display:block;border:0;max-width:none}
.lst-root [hidden]{display:none!important}
.lst-root .nS4_124_1154{align-content:stretch;display:flex;gap:9px;align-items:center;position:relative;flex-shrink:0}
.lst-root .nS4_124_1155{position:relative;flex-shrink:0;width:6px;height:6px}
.lst-root .x400010{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.lst-root .nS4_124_1156{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:17px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text, #f8f8f8);font-size:14px;white-space:nowrap;width:92px}
.lst-root [data-name="Widget/Sensor Status"] > * > *{margin-left:0;margin-top:0}
.lst-root [data-node-id$=";13:354"]{border-image:linear-gradient(to bottom,var(--wa-line, #fff) 60%,var(--wa-point, #7cccff) 60%) 1}
.lst-root [data-node-id="122:1076"]{border-color:transparent!important;outline:1px solid var(--wa-point, #273458);outline-offset:-0.5px}
.lst-root [data-node-id="124:1190"]{border-color:transparent!important;outline:1px solid var(--wa-point, #273458);outline-offset:-0.5px}
.lst-root [data-node-id="124:1235"]{border-color:transparent!important;outline:1px solid var(--wa-point, #273458);outline-offset:-0.5px}
.lst-root{position:absolute;inset:0;background:transparent;z-index:auto;overflow:visible}
.lst-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.lst-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.lst-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.lst-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.lst-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.lst-root[data-theme="light"] .nS4_124_1156{color:var(--wa-text, #141517)}
